// TIKTOK SHOP NIGHTLY 2h sáng (giờ VN) — kéo PHÍ / ĐỐI SOÁT từ TikTok Shop Open API vào Bronze.
//
// BẤT BIẾN #2: dữ liệu này CHỈ dùng cho phí / tiền thực nhận / hoa hồng affiliate.
// TUYỆT ĐỐI KHÔNG lấy đơn hay GMV TikTok làm DOANH THU — doanh thu chỉ từ Pancake, lấy cả 2 nguồn
// là đếm 2 lần cùng một giao dịch.
//
// BẤT BIẾN payload: n8n KHÔNG parse JSON của các stream dữ liệu (`json:false` + `encoding:"text"`).
// `json:false` MỘT MÌNH KHÔNG ĐỦ: nó chỉ đổi header Accept, axios vẫn JSON.parse body ⇒ int64
// (id đơn TikTok 18–19 chữ số) bị làm tròn, hỏng khoá. Chuỗi thô đi thẳng sang app; Postgres cast ::jsonb.
// Ngoại lệ DUY NHẤT: lời gọi REFRESH TOKEN + đọc/ghi kho token của app được parse (envelope chỉ có
// token + epoch, không có int64).
//
// TOKEN — NGUỒN SỰ THẬT LÀ APP (`/api/ingest/tiktok-token`, bảng Setting), KHÔNG dùng
// `getWorkflowStaticData`: n8n chỉ ghi static data KHI EXECUTION KẾT THÚC, và ở lần chạy TAY thì
// KHÔNG ghi gì cả. TikTok XOAY VÒNG refresh_token (refresh xong là cái cũ chết NGAY) ⇒ nếu token mới
// chỉ nằm trong bộ nhớ execution, chỉ cần một request dữ liệu throw sau bước refresh (rate-limit khi
// backfill 60 ngày là chuyện thường) là token mới bốc hơi, token cũ đã chết: ĐỨT CHUỖI VĨNH VIỄN,
// phải cấp quyền lại bằng tay. Vì chỉ được DUY NHẤT 1 hệ refresh, mất là không tự phục hồi.
// ⇒ Thứ tự BẮT BUỘC: nạp token từ app → (nếu cần) refresh → LƯU BỀN token mới về app → RỒI MỚI kéo
//   dữ liệu. Không một request dữ liệu nào được chạy trong khoảng "đã đốt refresh_token, chưa lưu".
//
// Token/refresh/lưu token lỗi ⇒ THROW (execution FAILED). KHÔNG nuốt lặng: hệ cũ nuốt lỗi nên token
// chết 12 ngày mà không ai biết.
//
// SECRET: app_key/app_secret/shop_cipher/shop_id + URL & secret của app nằm ở bảng `app."Setting"`
// (cùng chỗ với token Meta/TikTok đã lưu từ trước — MỘT nơi duy nhất để tra khoá, mở bảng là thấy).
// Node "Lấy khoá từ bảng Setting" chạy trước và truyền xuống đây; khoá gốc để mở kho khoá là
// credential Postgres do n8n giữ (mã hoá, không hiện trong execution log), role `n8n_config_ro` CHỈ
// được SELECT đúng bảng Setting — không đọc được đơn hàng, không ghi được gì.
// Đổi khoá = sửa 1 ô trong bảng, KHÔNG phải sửa file .env rồi dựng lại container.
// Không còn khoá nào nằm trong workflow ⇒ file trong repo KHỚP TUYỆT ĐỐI bản đang chạy, diff được.
// Token TikTok (access/refresh) vẫn đi qua kho token của app vì còn phải GHI token mới sau mỗi lần
// xoay vòng — role đọc-bảng này cố tình không có quyền ghi.
/**
 * Khoá lấy từ node "Lấy khoá từ bảng Setting" (mỗi dòng = 1 cặp key/value của bảng `app."Setting"`).
 * Node đó KHÔNG trả dòng nào ⇒ hoặc query sai, hoặc credential hỏng, hoặc bảng bị xoá key — dừng ngay
 * thay vì chạy tiếp với CONFIG rỗng rồi đổ lỗi nhầm cho TikTok.
 */
const KHOA = Object.fromEntries($input.all().map((i) => [i.json.key, i.json.value]));
if (!Object.keys(KHOA).length) {
  throw new Error(
    'Node "Lấy khoá từ bảng Setting" không trả về dòng nào — kiểm credential Postgres ' +
      '(role n8n_config_ro) và bảng app."Setting".'
  );
}

const CONFIG = {
  base: "https://open-api.tiktokglobalshop.com",
  authBase: "https://auth.tiktok-shops.com",
  // SECRET KHÔNG NẰM TRONG WORKFLOW — lấy từ bảng Setting (xem KHOA ở trên). Hardcode trong Code
  // node là khoá đi thẳng vào DB n8n + MỌI bản backup + MỌI execution log (đọc log lỗi là thấy
  // app_secret), đổi khoá phải sửa tay từng workflow, và file trong repo buộc phải để placeholder
  // nên bản repo KHÔNG BAO GIỜ khớp bản live — không diff được, không biết bản nào đúng.
  appUrl: KHOA.n8nAppUrl, // http://hogikids-app:3000 (trong mạng docker)
  ingestSecret: KHOA.n8nIngestSecret, // == INGEST_SECRET trong .env app
  appKey: KHOA.tiktokShopAppKey,
  appSecret: KHOA.tiktokShopAppSecret,
  shopCipher: KHOA.tiktokShopCipher,
  // shopId TikTok Shop — KHÁC id shop TikTok bên Pancake (100975192). Đây là khoá `shopId` của Bronze.
  // App CHẶN nếu điền nhầm id Pancake vào đây (landRaw kiểm shopId ∈ shops của stream).
  shopId: KHOA.tiktokShopShopId,
  pageSize: 50,
  // NHỊP GỌI — chống 429 (TikTok chặn vì gọi quá dày). Trước đây nghỉ 600ms giữa các trang
  // ≈ 100 request/phút, đúng bằng trần rate-limit nên chạm 429 là chuyện sớm muộn.
  pageDelayMs: 1200, // giữa 2 trang của cùng một endpoint (≈50 request/phút)
  statementDelayMs: 2000, // giữa 2 statement — vòng lặp transactions là nơi bắn dày nhất
  // Cửa sổ mặc định 7 ngày cho MỌI lượt (theo lịch lẫn bấm tay — không còn nhánh nhận diện
  // chế độ chạy). Statement chỉ chốt sau khi đơn hoàn tất nên 7 ngày phủ đủ; Bronze dedupe
  // theo hash ⇒ chồng lấn miễn phí. Cần kéo rộng hơn thì thêm key `tiktokShopManualDays`
  // (SỐ NGUYÊN 1–180) vào bảng Setting, ĐỪNG sửa số ở đây — xem ghi chú "Cửa sổ ngày" dưới.
  nightlyDays: 7,
};

// Thiếu khoá ⇒ dừng NGAY, nói rõ thiếu key nào. Không có guard này thì lỗi hiện ra dưới dạng
// 401/sai chữ ký ở tận request đầu tiên — mất công truy ngược.
const KHOA_THIEU = Object.entries({
  n8nAppUrl: CONFIG.appUrl,
  n8nIngestSecret: CONFIG.ingestSecret,
  tiktokShopAppKey: CONFIG.appKey,
  tiktokShopAppSecret: CONFIG.appSecret,
  tiktokShopCipher: CONFIG.shopCipher,
  tiktokShopShopId: CONFIG.shopId,
})
  .filter(([, v]) => !v)
  .map(([k]) => k);
if (KHOA_THIEU.length) {
  throw new Error(
    `THIẾU KHOÁ trong bảng app."Setting": ${KHOA_THIEU.join(", ")}. ` +
      `Thêm dòng key/value tương ứng rồi chạy lại — không cần đụng file cấu hình hay dựng lại container.`
  );
}

/** Trần trang / endpoint. Chạm trần = THROW (xem pullAll): thoát êm sẽ cắt cụt dữ liệu trong im lặng. */
const MAX_PAGES = 500;

const http = this.helpers.httpRequest;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const nowSec = () => Math.floor(Date.now() / 1000);

// Cửa sổ ngày — MỘT nguồn duy nhất: key `tiktokShopManualDays` trong bảng Setting ép cửa sổ cho MỌI
// lượt (theo lịch lẫn bấm tay); không có key thì dùng `nightlyDays`.
//
// Trước đây có nhánh "bấm tay ⇒ backfill 180 ngày" nhận diện bằng `$execution.mode !== "trigger"`,
// kèm ghi chú khẳng định n8n không có mode nào tên "test". ĐO THẬT 26/07/2026 — biến này CHỈ nhận 2
// giá trị: lịch cron ⇒ "production" (execution 104563), bấm tay ⇒ "test" (execution 104562). KHÔNG bao
// giờ là "trigger" — đó là nhãn của REST /executions, khác hẳn biến trong Code node, và chính chỗ nhầm
// hai thứ đó đẻ ra lỗi này ⇒ điều kiện cũ đúng với CẢ HAI, không phân biệt được gì. Hệ quả:
// hễ ai xoá key thì lượt tự động mỗi đêm nuốt trọn 180 ngày ≈ 980 statement, ~50 phút, dễ chạm 429 và
// trần 3600s của runner. Nay mặc định LUÔN là cửa sổ hẹp: mọi hiểu nhầm về chế độ chạy đều rơi về phía
// an toàn, và `execMode` cuối lượt in giá trị thô để lần sau khỏi phải suy đoán.
//
// Cần backfill: đặt `tiktokShopManualDays` = 180 → chạy tay → trả key về 7 (hoặc xoá key).
//
// TRẦN 180 NGÀY — ở đây là trần VẬT LÝ, không phải trần cho đẹp: 180 ngày ≈ 980 statement, mà
// mỗi statement phải nghỉ `statementDelayMs` 2000ms cộng `pageDelayMs` 1200ms giữa các trang
// ⇒ ~50 phút, đã sát trần 3600s của runner (N8N_RUNNERS_TASK_TIMEOUT). Đặt rộng hơn thì lượt
// chạy CHẮC CHẮN bị cắt giữa chừng — mất công gọi mà dữ liệu vẫn thiếu.
//
// ⚠️ CHẠY LẠI NHIỀU LƯỢT KHÔNG LÙI SÂU HƠN ĐƯỢC (đừng tin lại lời khuyên cũ ở đây): cửa sổ luôn
// neo `windowEnd = nowSec()` rồi trừ ngược, nên lượt thứ hai lấy ĐÚNG khoảng gần nhất y như lượt
// đầu, chỉ tốn thêm ~50 phút. Muốn xa hơn 180 ngày thì phải sửa workflow cho nhận thêm mốc KẾT
// THÚC để trượt cửa sổ về quá khứ (chưa làm — chưa có nhu cầu thật).
const MAX_MANUAL_DAYS = 180;

/**
 * Đọc số ngày ép từ một ô của bảng Setting. Trả 0 = KHÔNG ép (dùng `nightlyDays`).
 * CHỈ nhận số nguyên từ 1 đến `tran`; mọi giá trị khác ⇒ THROW.
 *
 * Vì sao không còn `Number(x) > 0` như bản trước: `"7.5"` cho mốc `since` lệch nửa ngày (sau này
 * rất khó truy ra vì sao thiếu/thừa một ngày), `"Infinity"` làm chính bước tính ngày NỔ giữa đêm
 * (đo 03/08/2026: workflow dùng `Intl.DateTimeFormat` ném `RangeError: Invalid time value`, workflow
 * dùng mốc epoch thì gửi lên API một cửa sổ vô nghĩa), `"100000"` bắn hàng nghìn request (chạm rate-limit và
 * trần 3600s của runner — N8N_RUNNERS_TASK_TIMEOUT), còn `"abc"` hay số âm thì rơi về mặc định
 * TRONG IM LẶNG: người vận hành đặt key xong tưởng đã backfill mà thực ra không.
 *
 * Vì sao THROW chứ không âm thầm về mặc định kèm cảnh báo: giá trị sai LUÔN do người vừa sửa bảng
 * Setting gõ nhầm — họ đang ở đó và thấy ngay execution FAILED. Hỏng một đêm KHÔNG mất dữ liệu:
 * cửa sổ thường trực là 7 ngày và Bronze dedupe theo hash nên lượt sau phủ lại phần thiếu.
 */
function soNgayCuaSo(key, giaTri, tran) {
  const s = String(giaTri === undefined || giaTri === null ? "" : giaTri).trim();
  if (s === "") return 0;
  if (!/^[0-9]+$/.test(s) || Number(s) < 1 || Number(s) > tran) {
    throw new Error(
      "Key " + key + ' = "' + s + '" KHÔNG hợp lệ — chỉ nhận SỐ NGUYÊN từ 1 đến ' + tran +
        " (không thập phân, không số âm, không chữ, không Infinity). Sửa lại ô đó trong bảng " +
        'app."Setting", hoặc XOÁ/để trống nó để quay về cửa sổ mặc định, rồi chạy lại.'
    );
  }
  return Number(s);
}

const daysEp = soNgayCuaSo("tiktokShopManualDays", KHOA.tiktokShopManualDays, MAX_MANUAL_DAYS);
const days = daysEp > 0 ? daysEp : CONFIG.nightlyDays;
const windowEnd = nowSec();
const windowStart = windowEnd - days * 86400;

const logs = [];
const results = [];

/** Token đang dùng trong execution này. Nạp từ app ở `loadToken()`, cập nhật ở `refreshAccessToken()`. */
let token = { accessToken: "", refreshToken: "", expireAt: 0, refreshExpireAt: 0 };

/**
 * HMAC-SHA256 hex. Ưu tiên module `crypto` của Node; nếu n8n không cho require (chưa bật
 * NODE_FUNCTION_ALLOW_BUILTIN) thì dùng WebCrypto toàn cục. Không có cả hai ⇒ THROW.
 */
async function hmacSha256Hex(secret, message) {
  try {
    const nodeCrypto = require("crypto");
    if (nodeCrypto && nodeCrypto.createHmac) {
      return nodeCrypto.createHmac("sha256", secret).update(message, "utf8").digest("hex");
    }
  } catch (e) {
    // require bị chặn → rơi xuống WebCrypto
  }
  const subtle = globalThis.crypto && globalThis.crypto.subtle;
  if (!subtle) {
    throw new Error(
      "Không ký được HMAC: thiếu cả require('crypto') lẫn WebCrypto. " +
        "Đặt NODE_FUNCTION_ALLOW_BUILTIN=crypto cho container n8n."
    );
  }
  const enc = new TextEncoder();
  const key = await subtle.importKey("raw", enc.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const sig = await subtle.sign("HMAC", key, enc.encode(message));
  return Array.from(new Uint8Array(sig))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

/**
 * Chữ ký TikTok: HMAC-SHA256(app_secret, app_secret + path + Σ(key+value đã SORT, BỎ sign &
 * access_token) + body + app_secret) → hex. GET ⇒ body rỗng.
 */
async function signQuery(path, qs) {
  const keys = Object.keys(qs)
    .filter((k) => k !== "sign" && k !== "access_token")
    .sort();
  const joined = keys.map((k) => `${k}${qs[k]}`).join("");
  return hmacSha256Hex(CONFIG.appSecret, `${CONFIG.appSecret}${path}${joined}${CONFIG.appSecret}`);
}

/** Nạp token đang dùng từ app. Kho rỗng (lần chạy đầu) ⇒ dùng hạt giống trong CONFIG. */
async function loadToken() {
  let res;
  try {
    res = await http({
      method: "GET",
      url: `${CONFIG.appUrl}/api/ingest/tiktok-token`,
      headers: { Authorization: `Bearer ${CONFIG.ingestSecret}` },
      json: true,
    });
  } catch (err) {
    throw new Error(
      `KHÔNG ĐỌC ĐƯỢC KHO TOKEN của app (${CONFIG.appUrl}/api/ingest/tiktok-token): ` +
        `${(err && err.message) || String(err)} — dừng TRƯỚC khi refresh để không đốt refresh_token khi chưa có chỗ lưu.`
    );
  }
  if (res && res.refreshToken) {
    token = {
      accessToken: res.accessToken,
      refreshToken: res.refreshToken,
      expireAt: Number(res.accessTokenExpireAt) || 0,
      refreshExpireAt: Number(res.refreshTokenExpireAt) || 0,
    };
    logs.push({ level: "INFO", message: `Nạp token từ app (lưu lúc epoch ${res.savedAt}), hạn epoch ${token.expireAt}` });
    return;
  }
  throw new Error(
    "KHO TOKEN CỦA APP RỖNG. Workflow không còn giữ token hạt giống (đã bỏ khi chuyển secret sang \$env) — " +
      "cấp quyền lại bằng scripts/tiktok-shop-lay-token.ts rồi nạp qua POST /api/ingest/tiktok-token."
  );
}

/**
 * LƯU BỀN token mới về app. Gọi NGAY sau refresh, TRƯỚC mọi request dữ liệu.
 * Lưu hỏng ⇒ THROW kèm token in ra rõ ràng: refresh_token cũ đã CHẾT, đây là bản duy nhất còn lại.
 */
async function persistToken(reason) {
  try {
    await http({
      method: "POST",
      url: `${CONFIG.appUrl}/api/ingest/tiktok-token`,
      headers: { Authorization: `Bearer ${CONFIG.ingestSecret}` },
      json: true,
      body: Object.assign(
        {
          accessToken: token.accessToken,
          refreshToken: token.refreshToken,
          accessTokenExpireAt: token.expireAt,
        },
        // Chỉ gửi khi TikTok có trả — app giữ nguyên mốc cũ nếu thiếu, không xoá.
        token.refreshExpireAt > 0 ? { refreshTokenExpireAt: token.refreshExpireAt } : {}
      ),
    });
  } catch (err) {
    throw new Error(
      `LƯU TOKEN MỚI VỀ APP THẤT BẠI (${reason}): ${(err && err.message) || String(err)}\n` +
        `⚠️ refresh_token CŨ ĐÃ CHẾT (TikTok xoay vòng). CHÉP NGAY cặp token dưới đây vào CONFIG/.env, ` +
        `nếu không phải cấp quyền lại bằng scripts/tiktok-shop-lay-token.ts:\n` +
        `access_token=${token.accessToken}\nrefresh_token=${token.refreshToken}\naccess_token_expire_at=${token.expireAt}`
    );
  }
  logs.push({
    level: "QUAN_TRỌNG",
    message: `ĐÃ LƯU token mới vào app (Setting) — ${reason}. access_token hết hạn lúc epoch ${token.expireAt}.`,
  });
}

/**
 * Refresh khi access_token đã hết hạn hoặc còn dưới 36h (NGUONG_GIA_HAN_GIAY, xem ensureFreshToken). Hạn không rõ ⇒ KHÔNG refresh mù (refresh sớm
 * là đốt refresh_token vô ích); đợi 401 mới refresh.
 * Refresh thành công ⇒ LƯU BỀN NGAY (persistToken). Không có khoảng hở "đã đốt, chưa lưu".
 */
async function refreshAccessToken(reason) {
  let res;
  try {
    res = await http({
      method: "GET",
      url: `${CONFIG.authBase}/api/v2/token/refresh`,
      qs: {
        app_key: CONFIG.appKey,
        app_secret: CONFIG.appSecret,
        refresh_token: token.refreshToken,
        grant_type: "refresh_token",
      },
      json: true, // envelope token: không có int64 → parse an toàn
    });
  } catch (err) {
    throw new Error(`REFRESH TOKEN LỖI (${reason}): ${(err && err.message) || String(err)} — cấp quyền lại bằng scripts/tiktok-shop-lay-token.ts`);
  }
  if (!res || res.code !== 0 || !res.data || !res.data.access_token) {
    throw new Error(
      `REFRESH TOKEN BỊ TỪ CHỐI (${reason}): code=${res && res.code} message=${res && res.message} — ` +
        `refresh_token có thể đã bị XOAY VÒNG bởi một hệ khác. Chỉ được DUY NHẤT 1 hệ refresh.`
    );
  }
  token = {
    accessToken: res.data.access_token,
    refreshToken: res.data.refresh_token,
    expireAt: Number(res.data.access_token_expire_in || 0),
    // TikTok trả kèm hạn của REFRESH token (~365 ngày, epoch giây). Đây là mốc DUY NHẤT cho biết khi
    // nào chuỗi tự gia hạn sẽ đứt — không lưu thì chỉ phát hiện lúc đã đứt, tức là đã mất dữ liệu.
    refreshExpireAt: Number(res.data.refresh_token_expire_in || 0),
  };
  // Scope app ĐANG CÓ — TikTok trả kèm ở chính lượt refresh này, trước nay bị vứt. Chỉ log TÊN scope
  // (KHÔNG log token) để biết đã có nhóm Analytics/Affiliate chưa mà không tốn thêm một request nào.
  const scopeDaCap = Array.isArray(res.data.granted_scopes) ? res.data.granted_scopes : [];
  logs.push({
    level: "INFO",
    message: "granted_scopes (" + scopeDaCap.length + "): " + (scopeDaCap.join(", ") || "(TikTok không trả trường này)"),
  });
  await persistToken(reason); // BẮT BUỘC trước khi bắn bất kỳ request dữ liệu nào
  return token.accessToken;
}

/**
 * NGƯỠNG GIA HẠN PHẢI LỚN HƠN KHOẢNG CÁCH GIỮA 2 LƯỢT CHẠY.
 *
 * Workflow chạy 1 lần/ngày (02:00). Ngưỡng cũ 2 GIỜ nghĩa là cửa sổ gia hạn chỉ mở 2 tiếng trước khi
 * token chết — mà 2 tiếng đó gần như luôn rơi vào GIỮA hai lượt chạy, nên lượt hôm trước thấy "còn
 * 24h, chưa cần" rồi lượt hôm sau token đã chết. Trước giờ chỉ thoát nhờ chữa cháy: đợi TikTok trả
 * 401 rồi mới gia hạn — tức là đã có một quãng gọi hỏng trước đó.
 *
 * 36 giờ = 1 ngày + biên 12h: gia hạn ở lượt chạy TRƯỚC ngày hết hạn, và nếu lượt đó lỗi (như vụ 429
 * đêm 25/07) thì lượt kế tiếp vẫn còn kịp. Đừng hạ xuống sát 24h — lỡ một đêm là mất token.
 */
const NGUONG_GIA_HAN_GIAY = 36 * 3600;
async function ensureFreshToken() {
  if (token.expireAt > 0 && token.expireAt - nowSec() < NGUONG_GIA_HAN_GIAY) {
    const conGio = Math.round((token.expireAt - nowSec()) / 3600);
    await refreshAccessToken(`còn ${conGio}h là hết hạn (ngưỡng ${NGUONG_GIA_HAN_GIAY / 3600}h)`);
  }
}

/**
 * 429 (rate limit) và 5xx là lỗi TẠM THỜI của phía TikTok, KHÔNG phải lỗi của ta.
 * Ném luôn = giết cả lượt sync đêm chỉ vì một cú nghẽn. Lùi rồi thử lại: 5s → 15s → 45s → 2m → 5m.
 * Rate-limit của TikTok tính theo CỬA SỔ THỜI GIAN, nên chờ tổng ~31s (3 bậc cũ) là chưa qua cửa sổ:
 * lượt đêm 25/07 chết ở statement_transactions đúng vì hết bậc mà cửa sổ chưa mở lại.
 */
const BACKOFF_MS = [5000, 15000, 45000, 120000, 300000];
function laLoiTamThoi(err) {
  const code = String((err && (err.httpCode || err.statusCode || (err.response && err.response.status))) || "");
  const msg = (err && err.message) || String(err);
  return code === "429" || /^5\d\d$/.test(code) || /status code (429|5\d\d)/.test(msg);
}

/** GET 1 trang TEXT THÔ (KHÔNG parse). 401/403 ⇒ refresh 1 lần rồi thử lại; vẫn hỏng ⇒ THROW. */
async function getRaw(path, params, retriedAfterRefresh, lanThu) {
  lanThu = lanThu || 0;
  const qs = Object.assign({}, params, {
    app_key: CONFIG.appKey,
    timestamp: nowSec(),
    shop_cipher: CONFIG.shopCipher,
  });
  qs.sign = await signQuery(path, qs);

  let text;
  try {
    text = await http({
      method: "GET",
      url: `${CONFIG.base}${path}`,
      qs,
      headers: { "x-tts-access-token": token.accessToken },
      json: false,
      encoding: "text", // BẮT BUỘC: thiếu nó axios vẫn parse ⇒ int64 hỏng
    });
  } catch (err) {
    const code = String((err && (err.httpCode || err.statusCode)) || "");
    const authish = code === "401" || code === "403" || /status code (401|403)/.test((err && err.message) || "");
    if (authish && !retriedAfterRefresh) {
      await refreshAccessToken("API trả 401/403"); // refresh + lưu bền, rồi mới thử lại
      return getRaw(path, params, true, lanThu);
    }
    // Lỗi TẠM THỜI (429/5xx): lùi rồi thử lại. Hết lượt mới chịu thua và KÊU TO.
    if (laLoiTamThoi(err) && lanThu < BACKOFF_MS.length) {
      const cho = BACKOFF_MS[lanThu];
      logs.push({ level: "CANH_BAO", message: `${path}: TikTok nghẽn (429/5xx), chờ ${cho / 1000}s rồi thử lại (lần ${lanThu + 1}/${BACKOFF_MS.length})` });
      await sleep(cho);
      return getRaw(path, params, retriedAfterRefresh, lanThu + 1);
    }
    throw new Error(`GET ${path} lỗi: ${(err && err.message) || String(err)}`);
  }

  if (typeof text !== "string") {
    throw new Error(`n8n trả object cho ${path}, không phải TEXT thô — thiếu encoding:'text'. int64 sẽ hỏng.`);
  }

  // `code` khác 0 = TikTok từ chối (token chết / sai chữ ký). Đọc bằng REGEX trên chuỗi thô.
  const codeMatch = text.match(/"code"\s*:\s*(-?\d+)/);
  const apiCode = codeMatch ? Number(codeMatch[1]) : null;
  if (apiCode !== 0) {
    const msg = (text.match(/"message"\s*:\s*"([^"]*)"/) || [])[1] || "";
    // Token hỏng giữa chừng (TikTok trả 200 + code lỗi) → refresh 1 lần rồi thử lại.
    if (!retriedAfterRefresh && /token|auth/i.test(msg)) {
      await refreshAccessToken(`API code=${apiCode} "${msg}"`);
      return getRaw(path, params, true, lanThu);
    }
    throw new Error(`TikTok từ chối ${path}: code=${apiCode} message="${msg}"`);
  }
  return text;
}

/** POST NGUYÊN chuỗi thô sang app — app tự bung mảng theo `arrayPath`, băm, dedupe. */
async function land(stream, text) {
  const r = await http({
    method: "POST",
    url: `${CONFIG.appUrl}/api/ingest/raw`,
    json: true,
    headers: { Authorization: `Bearer ${CONFIG.ingestSecret}` },
    body: { stream, shopId: CONFIG.shopId, payload: text },
  });
  results.push({
    stream,
    landed: r && r.stats ? r.stats.landed : undefined,
    mode: r && r.stats ? r.stats.mode : undefined,
  });
}

const NEXT_TOKEN = /"next_page_token"\s*:\s*"([^"]+)"/;
/** `"id":"…"` — KHÔNG khớp `"payment_id"`/`"order_id"` vì cần dấu nháy ngay trước `id`. */
const ID_IN_ARRAY = /"id"\s*:\s*"(\d{6,})"/g;

/**
 * Kéo HẾT trang của 1 endpoint (next_page_token) → land từng trang. Trả TEXT thô của mọi trang.
 *
 * KÊU TO, KHÔNG NUỐT LẶNG (cùng tinh thần land-raw.ts):
 *  - `next_page_token` LẶP LẠI không đổi (bug phân trang của API) ⇒ THROW. Không thì cùng một trang
 *    bị kéo lại tới khi chạm trần, đốt hàng phút vô ích mà dữ liệu thật vẫn thiếu.
 *  - Chạm trần MAX_PAGES mà VẪN CÒN next_page_token ⇒ THROW. Thoát êm = dữ liệu bị CẮT CỤT trong im
 *    lặng, execution vẫn xanh, không ai biết là thiếu.
 */
async function pullAll(path, params, stream) {
  const pages = [];
  let pageToken = "";
  let guard = 0;

  for (;;) {
    const qs = Object.assign({}, params, { page_size: CONFIG.pageSize });
    if (pageToken) qs.page_token = pageToken;

    const text = await getRaw(path, qs);
    await land(stream, text);
    pages.push(text);
    guard++;

    const m = text.match(NEXT_TOKEN);
    const nextToken = m ? m[1] : "";
    if (!nextToken) break; // hết trang — đường ra DUY NHẤT không phải lỗi

    if (nextToken === pageToken) {
      throw new Error(
        `PHÂN TRANG KẸT ở ${path}: next_page_token không đổi ("${nextToken}") sau trang ${guard} — ` +
          `TikTok trả đi trả lại cùng một trang. Dừng để không kéo vô hạn và không cắt cụt dữ liệu trong im lặng.`
      );
    }
    if (guard >= MAX_PAGES) {
      throw new Error(
        `${path}: chạm trần ${MAX_PAGES} trang mà VẪN CÒN next_page_token — dữ liệu sẽ bị CẮT CỤT. ` +
          `Thu hẹp cửa sổ ngày (key tiktokShopManualDays) hoặc nâng trần có chủ đích.`
      );
    }

    pageToken = nextToken;
    await sleep(CONFIG.pageDelayMs); // né rate-limit (hàng trăm request liên tiếp khi backfill)
  }
  return pages;
}

// TOKEN TRƯỚC, DỮ LIỆU SAU. Nạp token bền từ app → refresh (nếu cần) + lưu bền ngay → rồi mới kéo.
await loadToken();
await ensureFreshToken();

/**
 * CẢNH BÁO SỚM hạn refresh token. Access token tự gia hạn nên không đáng lo; refresh token thì hết
 * hạn là ĐỨT CHUỖI, phải cấp quyền lại bằng tay — nên phải biết TRƯỚC, không đợi hỏng mới biết.
 * Chưa có mốc (token lưu trước 2026-07-25) ⇒ im lặng: mốc sẽ tự có sau lần gia hạn kế tiếp.
 */
const REFRESH_CANH_BAO_NGAY = 30;
if (token.refreshExpireAt > 0) {
  const conNgay = Math.floor((token.refreshExpireAt - nowSec()) / 86400);
  if (conNgay <= 0) {
    throw new Error(
      `REFRESH TOKEN ĐÃ HẾT HẠN (mốc epoch ${token.refreshExpireAt}). Chuỗi tự gia hạn đứt — cấp quyền ` +
        `lại bằng scripts/tiktok-shop-lay-token.ts rồi nạp qua POST /api/ingest/tiktok-token.`
    );
  }
  if (conNgay < REFRESH_CANH_BAO_NGAY) {
    logs.push({
      level: "CANH_BAO",
      message: `⚠️ REFRESH TOKEN còn ${conNgay} ngày. Hết hạn là ĐỨT CHUỖI, phải cấp quyền lại bằng tay: ` +
        `scripts/tiktok-shop-lay-token.ts`,
    });
  } else {
    logs.push({ level: "INFO", message: `Refresh token còn ${conNgay} ngày` });
  }
} else {
  logs.push({
    level: "INFO",
    message: "Chưa biết hạn refresh token — sẽ có sau lần gia hạn kế tiếp (TikTok trả refresh_token_expire_in)",
  });
}

// (1) STATEMENTS — mỗi statement = 1 kỳ đối soát (tiền TikTok thực trả).
const statementPages = await pullAll(
  "/finance/202309/statements",
  { sort_field: "statement_time", statement_time_ge: windowStart, statement_time_lt: windowEnd },
  "tiktok/statements"
);

// (2) STATEMENT_TRANSACTIONS bản 202501 — BẮT BUỘC dùng 202501, KHÔNG dùng 202309: chỉ bản này trả
// `type` (ORDER | GMV_PAYMENT_FOR_TIKTOK_ADS | …). GMV Pay = TikTok Ads gom chi tiêu tới NGƯỠNG rồi
// trừ thẳng vào số dư bán hàng; ngưỡng THAY ĐỔI theo thời gian ⇒ chỉ nhận diện được bằng `type`,
// KHÔNG bằng số tiền. Mảng cũng khác: 202501 → data.transactions, 202309 → data.statement_transactions.
// (2b) statement_transactions của TỪNG statement — nơi có phí thật theo đơn (platform_commission,
// affiliate_commission, affiliate_ads_commission…). Rút statement id bằng REGEX trên chuỗi thô.
const statementIds = [];
for (const text of statementPages) {
  ID_IN_ARRAY.lastIndex = 0;
  let m;
  while ((m = ID_IN_ARRAY.exec(text)) !== null) {
    if (!statementIds.includes(m[1])) statementIds.push(m[1]);
  }
}

// Một statement nghẽn KHÔNG được giết cả lượt: trước đây throw ngay ở đây làm mất luôn bước
// PAYMENTS và mọi statement phía sau, dù phần đã kéo được vẫn hợp lệ. Nay gom lỗi rồi chạy tiếp,
// cuối cùng VẪN THROW (kêu to) — chỉ khác là dữ liệu kéo được đã nằm an toàn trong Bronze.
const loiTungPhan = [];
for (let i = 0; i < statementIds.length; i++) {
  const sid = statementIds[i];
  if (i > 0) await sleep(CONFIG.statementDelayMs);
  try {
    await pullAll(
      `/finance/202501/statements/${sid}/statement_transactions`,
      { sort_field: "order_create_time" },
      "tiktok/statement_transactions"
    );
  } catch (err) {
    const msg = (err && err.message) || String(err);
    loiTungPhan.push(`statement ${sid}: ${msg}`);
    logs.push({ level: "LOI", message: `statement ${sid} KHÔNG kéo được transactions: ${msg}` });
  }
}

// (3) PAYMENTS — tiền TikTok đã chuyển về tài khoản ngân hàng.
try {
  await pullAll(
    "/finance/202309/payments",
    { sort_field: "create_time", create_time_ge: windowStart, create_time_lt: windowEnd },
    "tiktok/payments"
  );
} catch (err) {
  const msg = (err && err.message) || String(err);
  loiTungPhan.push(`payments: ${msg}`);
  logs.push({ level: "LOI", message: `payments KHÔNG kéo được: ${msg}` });
}

if (loiTungPhan.length) {
  throw new Error(
    `${loiTungPhan.length}/${statementIds.length + 1} phần KHÔNG kéo được (phần còn lại ĐÃ vào Bronze):\n` +
      loiTungPhan.join("\n")
  );
}

const landedTotal = results.reduce((s, r) => s + (Number(r.landed) || 0), 0);
return [
  {
    json: {
      mode: daysEp > 0 ? `cửa sổ ép ${daysEp} ngày (key tiktokShopManualDays)` : "mặc định (nightlyDays)",
      execMode: $execution.mode, // giá trị THẬT n8n trả cho biến này — ghi lại để khỏi phải đoán
      days,
      window: { start: windowStart, end: windowEnd },
      accessTokenConLaiGio: token.expireAt > 0 ? Math.round((token.expireAt - nowSec()) / 3600) : null,
      refreshTokenConLaiNgay: token.refreshExpireAt > 0 ? Math.floor((token.refreshExpireAt - nowSec()) / 86400) : null,
      statements: statementIds.length,
      calls: results.length,
      landedTotal,
      logs,
      results,
    },
  },
];
